export function smuflGlyph(code, x = 72, y = 72, size = 82, mirror = false) {
  const glyph = glyphs[String(code).replace(/^0x/, '').toLowerCase()];
  if (!glyph) return '';
  const scale = size / Math.max(glyph.w, glyph.h);
  const yScale = mirror ? scale : -scale;
  const transform = `translate(${x} ${y}) scale(${scale} ${yScale}) translate(${-glyph.cx} ${-glyph.cy})`;
  return `<path d="${glyph.d}" transform="${transform}" fill="currentColor"/>`;
}
